import {Session} from 'node:inspector';
import {mkdirSync,writeFileSync} from 'node:fs';
import {join,resolve} from 'node:path';
import {threadId,isMainThread} from 'node:worker_threads';
export function createCpuProfiler(directory,execution){
 const root=resolve(directory);mkdirSync(root,{recursive:true});
 const session=new Session();session.connect();
 const post=(method,params={})=>{let done=false,value,error;session.post(method,params,(err,result)=>{done=true;error=err;value=result;});if(!done)throw Error('Synchronous Inspector required: '+method);if(error)throw error;return value;};
 post('Profiler.enable');post('Profiler.setSamplingInterval',{interval:1000});
 let active,sequence=0;
 const save=(path,value)=>writeFileSync(path,JSON.stringify(value)+'\n',{flag:'wx'});
 save(join(root,'run.json'),{kind:'CPU_ONLY_NO_HEAP_PROFILER_NO_FORCED_GC',acceptanceEvidence:false,execution,runtime:{versions:process.versions,execArgv:process.execArgv,execPath:process.execPath},pid:process.pid,threadId,isMainThread,samplingIntervalUs:1000,profileScope:'Worker-isolate elapsed samples, not processCPU; check interval includes final request/input hash verification before finally',phaseCpuScope:'Original driver phase process.cpuUsage including helper threads'});
 function stop(boundary,status='completed'){
  if(!active)return;const interval=active;
  const ended=performance.now(),cpuUs=process.cpuUsage(interval.cpuStart);
  const {profile}=post('Profiler.stop');active=undefined;
  save(interval.stem+'.cpuprofile',profile);
  save(interval.stem+'.json',{phase:interval.phase,status,boundary,profilePath:interval.stem+'.cpuprofile',wallMs:ended-interval.started,cpuUs,details:interval.details,sampledIsolateOnly:true,allocationSampling:false,explicitGC:false});
 }
 return {mark(phase,details={}){stop({phase,details});const stem=join(root,String(++sequence).padStart(2,'0')+'-'+phase);post('Profiler.start');active={phase,details,stem,started:performance.now(),cpuStart:process.cpuUsage()};},finish(error){try{stop({phase:'finally',error:error?String(error):undefined},error?'error':'completed');}finally{session.disconnect();}}};
}

#!/usr/bin/env bun
// Comparable clean root-to-JS runs. Source algorithms and artifacts are pinned;
// this driver performs IO and advances opaque native-owned Run values only.
import {createHash} from 'node:crypto';
import {readFileSync,writeFileSync,existsSync,realpathSync} from 'node:fs';
import {resolve,dirname,posix,isAbsolute} from 'node:path';
import {pathToFileURL,fileURLToPath} from 'node:url';
import {Worker,isMainThread,workerData} from 'node:worker_threads';
import {getHeapStatistics} from 'node:v8';
import {runHeavyGate} from 'file:///Users/ilyagulya/Projects/My/bend/evals/heavy_gate.ts';
import {ABI,workloadRows,corpusFor,runtimeManifest,runNativeStage0,requireNativeRun} from 'file:///Users/ilyagulya/Projects/My/bend/evals/native_seed_runtime.mjs';
import {runTemplateSteps,runCheckerSteps,runLibraryEmitterSteps,sourceFiles,sourceFileTagFromRoot} from 'file:///Users/ilyagulya/Projects/My/bend/evals/checker_core_step_runtime.mjs';
import {createCpuProfiler} from 'file:///var/folders/0r/pkz80d0154z37ybnv69pqclh0000gn/T/bend-build-acceleration-3cg3qjns/g72-cpu-causality-o2arrjf5/cpu-only-inspector.mjs';

const script=fileURLToPath(import.meta.url);
const sha=bytes=>createHash('sha256').update(bytes).digest('hex');
const hash=path=>sha(readFileSync(path));
const save=(path,value)=>writeFileSync(path,JSON.stringify(value,null,2)+'\n');
const tag=value=>typeof value?.$==='string'?value.$.split('.').at(-1):null;
const items=value=>{const out=[];while(tag(value)==='Con'){out.push(value.head);value=value.tail;}if(tag(value)!=='Nil')throw Error('Malformed native list');return out;};
const list=values=>values.reduceRight((tail,head)=>({$:'Con',head,tail}),{$:'Nil'});
const fuelEnd=Object.freeze({$:'FeedbackFuelEnd'}),fuelPrototype={get tail(){return fuel(this.remaining-1);}};
function fuel(remaining){if(remaining===0)return fuelEnd;const node=Object.create(fuelPrototype);node.$='FeedbackFuelCell';node.remaining=remaining;return node;}
function verify(pins){for(const [path,digest]of Object.entries(pins))if(realpathSync(path)!==path||hash(path)!==digest)throw Error('Pinned input drift: '+path);}
function requestAt(path){
  const request=JSON.parse(readFileSync(path,'utf8'));
  if(request.schemaVersion!==1||!request.pins||!request.inputs||JSON.stringify(request.exports)!==JSON.stringify(ABI))throw Error('Invalid throughput request');
  if(request.limits?.memoryMiB!==8192||request.limits?.rssMiB!==8192||request.limits?.timeoutMs!==600000)throw Error('Throughput guard must retain original limits');
  if(!['check','compile'].includes(request.stopAfter??'compile'))throw Error('Invalid throughput stopAfter');
  if(request.stopAfter==='check'&&request.expectedSelfhostOutput!==undefined)throw Error('Check-only runs cannot claim emitted output equality');
  verify(request.pins);verify(request.inputs);
  return request;
}
async function run(mode,requestPath,requestSha256,reportPath){
  if(hash(requestPath)!==requestSha256)throw Error('Throughput request drift');
  const request=requestAt(requestPath),output=reportPath+'.output.mjs';
  if(request.stopAfter==='check'&&mode!=='js')throw Error('Check-only mode requires the actual JS component pipeline');
  if(existsSync(output))throw Error('Output path already exists');
  const report={schemaVersion:1,status:'RUNNING',diagnosticOnly:true,acceptanceEvidence:false,mode,request:requestPath,requestSha256,source:request.root,sourceSha256:hash(request.root),runtime:{execPath:process.execPath,versions:process.versions,execArgv:process.execArgv,heapLimitBytes:getHeapStatistics().heap_size_limit},limits:request.limits,workerPolicy:{stackMiB:256,oldGenerationMiB:6144,youngGenerationMiB:128},exports:ABI,phases:[],checksExcluded:0,outputPatches:0};
  report.stopAfter=request.stopAfter??'compile';
  const started=performance.now();save(reportPath,report);
  const profileDirectory=process.env.SELFHOST_CPU_PROFILE_DIR;
  const profiler=profileDirectory?createCpuProfiler(profileDirectory,{mode,root:request.root,image:request.image,request:requestPath,requestSha256}):undefined;
  let profileError;
  const phase=async(name,action)=>{
    profiler?.mark(name,{root:request.root,mode});
    const before=performance.now(),cpu=process.cpuUsage();report.activePhase=name;save(reportPath,report);
    const result=await action(),used=process.cpuUsage(cpu);
    report.phases.push({phase:name,elapsedMs:performance.now()-before,userCpuMs:used.user/1000,systemCpuMs:used.system/1000,memoryEnd:process.memoryUsage()});delete report.activePhase;save(reportPath,report);return result;
  };
  try{
    let source;
    if(mode==='native'){
      const work=workloadRows(request.root,'js'),corpus=corpusFor(work);
      if(JSON.stringify(Object.fromEntries([...work.sources,...work.externals].map(row=>[row.file,row.sha256]).sort()))!==JSON.stringify(Object.fromEntries(Object.entries(request.inputs).sort())))throw Error('Native source closure differs from request');
      const manifest=reportPath+'.runtime.tsv',exportsPath=reportPath+'.exports.txt';
      writeFileSync(manifest,runtimeManifest(corpus),{flag:'wx'});writeFileSync(exportsPath,ABI.join('\n')+'\n',{flag:'wx'});
      const native=runNativeStage0(request.binary,{root:request.root,base:resolve(request.repository,'bend2/base.bend'),manifest,exports:exportsPath,phase:'compile',output},{timeoutMs:request.limits.timeoutMs});
      writeFileSync(reportPath+'.native.stdout',native.stdout,{flag:'wx'});writeFileSync(reportPath+'.native.stderr',native.stderr,{flag:'wx'});
      requireNativeRun(native,{phases:['parse','expand','check','emit'],sources:work.sources.length,output});
      report.native={command:native.command,status:native.status,signal:native.signal,elapsedMs:native.elapsedMs,begins:native.begins,fuel:native.fuel,result:native.results};
      report.phases=native.phases;report.moduleCount=work.sources.length;
      report.phaseCpuScope='Native process RUSAGE_SELF; wrapper and guardian excluded';
    }else if(mode==='ts'){
      const {K,C}=await phase('startup',async()=>({K:await import(pathToFileURL(resolve(request.repository,'bend2/bend.ts')).href),C:await import(pathToFileURL(resolve(request.repository,'bend2/comp.ts')).href)}));
      const book=K.book_nil(),observed=new Set();
      class Inputs extends Map{set(path,namespace){if(namespace===null)observed.add(realpathSync(path));return super.set(path,namespace);}}
      await phase('load-parse-expand',()=>K.book_load(book,request.root,'',new Inputs()));
      for(const def of Object.values(book.tlds))if(def.$==='Def')for(const path of def.i??[])if(path.endsWith('.js'))observed.add(realpathSync(path));
      if(observed.size!==Object.keys(request.inputs).length||[...observed].some(path=>!Object.hasOwn(request.inputs,path)))throw Error('TS source closure differs from request');
      await phase('check',()=>K.book_valid(book));
      if(book.hols)throw Error('Unfilled TS book');
      const definitions=Object.values(book.tlds).filter(def=>def.$==='Def'&&def.v!==null);
      if(definitions.some(def=>def.e===undefined))throw Error('Unchecked TS body');
      report.checkedDefinitions=definitions.length;report.validationEvents=book.order.length;
      source=await phase('emit',()=>C.js_lib(book,true,ABI));
      report.phaseCpuScope='Node process-wide CPU; includes worker/helper threads, excludes child processes';
    }else if(mode==='js'){
      const api=await phase('startup',async()=>(await import(pathToFileURL(request.image).href)).default);
      if(!api||!ABI.every(key=>typeof api[key]==='function'))throw Error('Emitted compiler ABI incomplete');
      let modules=[],files=[],declarations=0;
      await phase('load-parse',()=>{
        const seen=new Map(),active=new Set(),observed=new Set(),foreign=new Map();
        const observe=path=>{const real=realpathSync(path);if(!Object.hasOwn(request.inputs,real))throw Error('Unexpected input: '+real);observed.add(real);return real;};
        const namespace=(scope,path)=>path==='Base'?'':posix.normalize(isAbsolute(path)?path.replace(/\.bend$/,''):posix.dirname(scope)+'/'+path.replace(/\.bend$/,''));
        const foreignSource=(file,path)=>{const real=observe(resolve(dirname(file),path));foreign.set(real,readFileSync(real,'utf8'));};
        const visit=(file,scope)=>{
          const real=observe(file);if(active.has(real))throw Error('Import cycle: '+real);
          if(seen.has(real)){if(seen.get(real)!==scope)throw Error('Namespace conflict');return;}seen.set(real,scope);active.add(real);
          const feedback=api.parse_with_fuel(fuel(8000000),real,readFileSync(real,'utf8'));
          if(tag(feedback)!=='FeedbackComplete'||tag(feedback.value.result)!=='ParseSuccess')throw Error('Own parser rejected '+real);
          const module=feedback.value.result.module;declarations+=items(module.declarations).length;
          for(const top of items(module.declarations))if(tag(top)==='DefTop'&&tag(top.definition.body)==='DefImports')for(const path of items(top.definition.body.paths))if(path.endsWith('.js'))foreignSource(real,path);
          for(const imported of items(module.imports)){const path=imported.path;if(path.endsWith('.js'))foreignSource(real,path);else if(!path.endsWith('.c'))visit(path==='Base'?resolve(request.repository,'bend2/base.bend'):resolve(dirname(real),path),namespace(scope,path));}
          modules.push(api.parsed_module(scope,module));active.delete(real);
        };
        visit(request.root,'');
        if(observed.size!==Object.keys(request.inputs).length)throw Error('Own parser omitted a frozen input');
        report.moduleCount=seen.size;report.sourceDeclarations=declarations;files=[...foreign].map(([path,source])=>({path,source}));modules=list(modules);
      });
      const stepCounts={};
      let expanded=await phase('expand',()=>runTemplateSteps({...api,expand_modules_start:input=>{modules=undefined;return api.expand_modules_start(input);}},modules,{onFinish(_,steps){stepCounts.expand=steps;}}));
      if(tag(expanded)!=='ExpandSuccess')throw Error('Own expansion failed');
      let checked=await phase('check',()=>runCheckerSteps({...api,check_expanded_start:input=>{expanded=undefined;return api.check_expanded_start(input);}},expanded.modules,{onFinish(_,steps){stepCounts.check=steps;}}));
      if(tag(checked)!=='CheckSuccess')throw Error('Own checking failed');
      if(request.stopAfter!=='check'){
        const carrier=sourceFileTagFromRoot(readFileSync(request.root,'utf8'),'selfhost');
        const emitted=await phase('emit',()=>runLibraryEmitterSteps({...api,emit_library_start:(program,names,sources)=>{checked=undefined;return api.emit_library_start(program,names,sources);}},checked.program,list(ABI),sourceFiles(files,carrier),{onFinish(_,steps){stepCounts.emit=steps;}}));
        if(tag(emitted)!=='EmitSuccess')throw Error('Own emission failed');source=emitted.source;
      }
      report.stepCounts=stepCounts;report.phaseCpuScope='Node process-wide CPU; includes worker/helper threads, excludes child processes';
    }else throw Error('Unknown throughput mode: '+mode);
    report.pipelineElapsedMs=performance.now()-started;
    if(source!==undefined){writeFileSync(output,source,{flag:'wx'});source=undefined;}
    if(request.stopAfter!=='check'){
      report.output={path:output,bytes:readFileSync(output).length,sha256:hash(output)};
      if(mode!=='ts'&&request.expectedSelfhostOutput&&report.output.sha256!==request.expectedSelfhostOutput)throw Error('Unchanged G21 output bytes differ');
    }
    verify(request.pins);verify(request.inputs);
    report.status='PASS';
  }catch(error){profileError=error;report.status='FAIL';report.error=String(error);report.stack=error?.stack;process.exitCode=1;}
  try{profiler?.finish(profileError);}catch(error){report.status='FAIL';report.error=String(error);report.stack=error?.stack;process.exitCode=1;}
  report.totalElapsedMs=performance.now()-started;save(reportPath,report);console.log(JSON.stringify({status:report.status,mode,report:reportPath,pipelineElapsedMs:report.pipelineElapsedMs,phases:report.phases.map(row=>({phase:row.phase,elapsedMs:row.elapsedMs})),output:report.output,error:report.error}));
}
if(!isMainThread){await run(workerData.mode,workerData.requestPath,workerData.requestSha256,workerData.reportPath);}
else if(process.argv[2]==='--worker'){
  const [,mode,requestPath,requestSha256,reportPath]=process.argv.slice(2);
  if(!mode||!requestPath||!requestSha256||!reportPath)throw Error('Expected worker arguments');
  const child=new Worker(new URL(import.meta.url),{workerData:{mode,requestPath,requestSha256,reportPath},resourceLimits:{stackSizeMb:256,maxOldGenerationSizeMb:6144,maxYoungGenerationSizeMb:128}});
  await new Promise((done,reject)=>{child.once('error',reject);child.once('exit',code=>code===0?done():reject(Error('Throughput worker failed: '+code)));});
}else{
  const [mode,requestPath,reportPath]=process.argv.slice(2);
  if(!['ts','native','js'].includes(mode)||!requestPath||!reportPath||process.argv.length!==5)throw Error('Usage: bun evals/selfhost_throughput.mjs ts|native|js REQUEST.json FRESH-REPORT.json');
  if(existsSync(reportPath))throw Error('Use a fresh report path');
  const request=requestAt(resolve(requestPath));save(reportPath,{schemaVersion:1,status:'RUNNING',mode,diagnosticOnly:true,acceptanceEvidence:false});
  const guarded=await runHeavyGate([request.node,'--experimental-strip-types','--max-old-space-size=6144','--max-semi-space-size=128',script,'--worker',mode,resolve(requestPath),hash(requestPath),resolve(reportPath)],{...request.limits,pollMs:10,label:'Frozen full-root throughput '+mode});
  const report=JSON.parse(readFileSync(reportPath,'utf8'));report.guardian=guarded;
  if(guarded.status!=='PASS'||report.status!=='PASS'){report.status='FAIL';process.exitCode=guarded.exitCode||1;}
  save(reportPath,report);
}

import {readFileSync,writeFileSync,realpathSync} from 'node:fs';
import {createHash} from 'node:crypto';
const [imagePath,summaryPath,emitPath,nullPath]=process.argv.slice(2);
if(!imagePath||!summaryPath)throw Error('Expected IMAGE CPU_SUMMARY [FRESH_DIAGNOSTIC_IMAGE]');
const parserModule={exports:{}};
const parserSource=process.binding('natives')['internal/deps/acorn/acorn/dist/acorn'];
new Function('exports','module',parserSource)(parserModule.exports,parserModule);
const source=readFileSync(imagePath,'utf8'),summary=JSON.parse(readFileSync(summaryPath,'utf8'));
if(source.includes('$g72Leaf_'))throw Error('Diagnostic temporary prefix collision');
const program=parserModule.exports.parse(source,{ecmaVersion:'latest',sourceType:'module',locations:true});
const hash=value=>createHash('sha256').update(value).digest('hex');
function children(node){const out=[];for(const [key,value]of Object.entries(node)){if(key==='loc')continue;if(Array.isArray(value)){for(const child of value)if(child&&typeof child.type==='string')out.push(child);}else if(value&&typeof value.type==='string')out.push(value);}return out;}
function scan(root,visit){const stack=[root];while(stack.length){const node=stack.pop();visit(node);stack.push(...children(node));}}
const declarations=new Map(),primitiveBodies=new Map();
for(const node of program.body){if(node.type==='FunctionDeclaration'){if(declarations.has(node.id.name))throw Error('Duplicate declaration');declarations.set(node.id.name,node);}if(node.type==='VariableDeclaration')for(const d of node.declarations)if(d.id.type==='Identifier'&&d.id.name.startsWith('$p_')&&['ArrowFunctionExpression','FunctionExpression'].includes(d.init?.type))primitiveBodies.set(d.id.name,d.init);}
const forbidden=new Set(['$TAIL_PENDING','$CALL_PENDING','$LEAVE_PENDING','$BEND_TAIL','$sp','$ksp','$tailFn','$tailCount','$stArgs','$kFn','$kBase','$kKind','$tailArgs','$tailRest','$tailUnary','$leaveThunk']);
function noSuspensionSyntax(body,allowedCalls){let reason;scan(body,node=>{if(reason)return;if(['FunctionExpression','ArrowFunctionExpression','FunctionDeclaration','ClassExpression','ClassDeclaration','AwaitExpression','YieldExpression','NewExpression','ImportExpression','WithStatement'].includes(node.type))reason=node.type;else if(node.type==='Identifier'&&forbidden.has(node.name))reason='scheduler-global:'+node.name;else if(node.type==='CallExpression'&&(node.callee.type!=='Identifier'||!allowedCalls.has(node.callee.name)))reason='unproved-call:'+source.slice(node.callee.start,node.callee.end);});return reason;}
function safeArgument(node){return node.type==='Literal'||node.type==='Identifier'&&(!forbidden.has(node.name)||node.name==='$td')||node.type==='BinaryExpression'&&['+','-'].includes(node.operator)&&safeArgument(node.left)&&safeArgument(node.right);}
const terminalPrimitives=new Set();
for(const [name,node]of primitiveBodies)if(!noSuspensionSyntax(node.body,new Set()))terminalPrimitives.add(name);
for(const [name,node]of declarations)if(name.startsWith('$p_')&&!noSuspensionSyntax(node.body,new Set()))terminalPrimitives.add(name);
const leaves=new Set(),leafRejections={};
for(const [name,node]of declarations){if(!/^\$b[0-9]+$/.test(name))continue;const reason=noSuspensionSyntax(node.body,terminalPrimitives);if(reason)leafRejections[reason]=(leafRejections[reason]??0)+1;else leaves.add(name);}
const sites=[],patches=[],parentBodies=new Set(),continuations=new Set();
for(const [owner,fn]of declarations){if(!/^\$[bk][0-9]+$/.test(owner))continue;scan(fn.body,node=>{
 if(node.type!=='IfStatement'||node.test.type!=='BinaryExpression'||node.test.operator!=='<'||node.test.left.type!=='Identifier'||node.test.left.name!=='$td'||node.test.right.type!=='Literal'||node.test.right.value!==64||node.consequent.type!=='BlockStatement')return;
 const branch=node.consequent;
 for(let i=1;i<branch.body.length;i++){
  const decl=branch.body[i-1],attempt=branch.body[i];
  if(decl.type!=='VariableDeclaration'||decl.declarations.length!==2||attempt.type!=='TryStatement'||attempt.finalizer||!attempt.handler||attempt.block.body.length!==1)continue;
  const [base,index]=decl.declarations,ret=attempt.block.body[0],done=ret.argument;
  if(base.id.type!=='Identifier'||index.id.type!=='Identifier'||base.init?.type!=='BinaryExpression'||base.init.operator!=='-'||base.init.left.type!=='Identifier'||base.init.left.name!=='$sp'||base.init.right.type!=='Literal'||!Number.isSafeInteger(base.init.right.value)||base.init.right.value<0)continue;
  if(index.init?.type!=='CallExpression'||index.init.callee.type!=='Identifier'||index.init.callee.name!=='$split_enter'||index.init.arguments.length!==2)continue;
  const [cont,kb]=index.init.arguments;
  if(cont.type!=='Identifier'||!/^\$k[0-9]+$/.test(cont.name)||kb.type!=='Identifier'||kb.name!==base.id.name)continue;
  if(ret.type!=='ReturnStatement'||done?.type!=='CallExpression'||done.callee.type!=='Identifier'||done.callee.name!=='$split_done'||done.arguments.length!==3)continue;
  const [call,ki,depth]=done.arguments;
  if(call.type!=='CallExpression'||call.callee.type!=='Identifier'||!leaves.has(call.callee.name)||ki.type!=='Identifier'||ki.name!==index.id.name)continue;
  const handler=attempt.handler,abort=handler.body.body[0],thrown=handler.body.body[1];
  if(handler.param?.type!=='Identifier'||handler.body.body.length!==2||abort.type!=='ExpressionStatement'||abort.expression.type!=='CallExpression'||abort.expression.callee.type!=='Identifier'||abort.expression.callee.name!=='$split_abort'||abort.expression.arguments.length!==2||thrown.type!=='ThrowStatement'||thrown.argument.type!=='Identifier'||thrown.argument.name!==handler.param.name)continue;
  if(abort.expression.arguments[0].type!=='Identifier'||abort.expression.arguments[0].name!==index.id.name||abort.expression.arguments[1].type!=='Identifier'||abort.expression.arguments[1].name!==base.id.name)continue;
  if(depth.type!=='BinaryExpression'||depth.operator!=='+'||depth.left.type!=='Identifier'||depth.left.name!=='$td'||depth.right.type!=='Literal'||depth.right.value!==1)continue;
  if(call.callee.name===owner||call.arguments.some(arg=>!safeArgument(arg)))continue;
  let indexUses=0;scan(branch,part=>{if(part.type==='Identifier'&&part.name===index.id.name)indexUses++;});if(indexUses!==3)continue;
  const continuation=declarations.get(cont.name),params=continuation?.params;
  if(!params||params.length!==3||params[0].type!=='Identifier'||params[1].type!=='Identifier'||params[1].name!=='$base'||params[2].type!=='AssignmentPattern'||params[2].left.type!=='Identifier'||params[2].left.name!=='$td'||params[2].right.type!=='Literal'||params[2].right.value!==0)continue;
  const code=source.slice(ret.start,ret.end),temporary='$g72Leaf_'+ret.start;
  const replacement='const '+temporary+'='+source.slice(call.start,call.end)+';$sp='+base.id.name+';return '+cont.name+'('+temporary+','+base.id.name+','+source.slice(depth.start,depth.end)+');';
  const site={owner,callee:call.callee.name,continuation:cont.name,spillCount:base.init.right.value,line1:decl.loc.start.line,frameRange:[index.init.start,index.init.end],returnRange:[ret.start,ret.end],originalFrame:source.slice(index.init.start,index.init.end),originalReturn:code,replacement};
  sites.push(site);parentBodies.add(owner);continuations.add(cont.name);patches.push({start:index.init.start,end:index.init.end,text:'$ksp'},{start:ret.start,end:ret.end,text:replacement});
 }
});}
patches.sort((a,b)=>a.start-b.start);for(let i=1;i<patches.length;i++)if(patches[i-1].end>patches[i].start)throw Error('Overlapping AST edits');
const relevant=row=>{try{return realpathSync(new URL(row.url))===realpathSync(imagePath);}catch{return false;}};
